from assemble_topic import assemble, W, read, dump, stamp
FACTS={
'01':('Dispersed, linear and nucleated settlement describe arrangements rather than household income or total population alone.','A settlement can combine forms and appear different at different mapping scales.'),
'01-01':('Dispersed dwellings lie apart across an area with intervening land.','Scattered spacing does not establish absent services or a particular ownership system.'),
'01-02':('Linear settlement follows an elongated route or strip that can be straight or curved.','Alignment alone does not establish the historical cause or every household’s water use.'),
'01-03':('Nucleated settlement groups dwellings in a compact cluster that need not be circular.','A cluster does not establish a large population, wealth or one necessary origin mechanism.'),
'02':('Physical setting, accessibility, farming arrangements, policy and history interact in rural settlement patterns.','Broad LEDC/MEDC labels do not assign one inevitable settlement form or service level.'),
'02-01':('Relief, soil and usable water influence feasible sites through construction, livelihoods and risk.','River proximity can offer access and flood exposure, requiring the actual local conditions.'),
'02-02':('Accessibility concerns feasible journeys to services, work and markets rather than straight-line distance alone.','Road proximity does not establish dependable affordable transport.'),
'02-03':('Agricultural holdings and work arrangements can influence dwelling spacing and field access.','Production purpose and settlement pattern are separate dimensions.'),
'02-04':('Land allocation, planning and historical restrictions can shape settlement opportunities.','A policy boundary alone does not establish implemented or compliant settlement.'),
'03':('Function, urban growth and urbanisation describe different settlement characteristics.','Urbanisation is a rising urban population share and can reflect natural change, migration or reclassification.'),
'04':('Urban morphology combines CBD, residential, industrial, shopping, open-space and transport functions.','Schematic models simplify relationships rather than supplying a measured map or universal social pattern.'),
'04-01':('CBD interpretation uses concentrated commercial functions and accessibility rather than height alone.','A city can contain multiple commercial nodes and changing functions.'),
'04-02':('Residential form, density, income and usable services require different evidence.','A tall building or peripheral location does not establish household welfare.'),
'04-03':('Industrial sites can depend on freight, land, utilities and compatible surroundings.','Large roofs alone do not identify manufacturing or its historical location.'),
'04-04':('Shopping areas differ in scale, access and potential catchments.','Customer origins require suitable evidence rather than inference from shop size.'),
'04-05':('Open space can serve recreation, ecology, drainage or other functions with different access.','Unbuilt appearance does not establish unused land or a maintained public park.'),
'04-06':('Transport routes connect uses while capacity, service and barriers affect practical access.','An added route or wider road does not establish a universal congestion reduction.'),
'05':('Urban problems can arise where suitable housing, services or transport access do not keep pace with need.','A solution must address the actual constraint and affected users rather than count construction alone.'),
'05-01':('CBD congestion involves a capacity, delay or access problem rather than activity alone.','Parking, delivery and public-transport measures affect different bottlenecks and can displace pressure.'),
'05-02':('Housing shortage can concern affordability, suitability, location and services as well as total dwellings.','Lower housing charges can coexist with higher combined transport and service costs.'),
'05-03':('Informal-settlement conditions vary and reflect constrained access to land, services and housing.','Upgrading can improve components while requiring affordability, maintenance and participation evidence.'),
'05-04':('Traffic counts, flow capacity and delay are different measures in congestion analysis.','A fall at one point can reflect rerouting rather than reduced citywide movement.'),
'06':('Urban development can change environmental pathways through land cover, demand and waste systems.','Urbanisation, footprint expansion and migration are related but distinct processes.'),
'06-01':('Urban air pollution depends on sources, emissions, dispersion and exposure.','Vehicle counts alone do not establish pollutant concentrations or clinical causation.'),
'06-02':('Unsuitable sewage, industrial discharge or runoff can affect receiving waters beyond urban boundaries.','A drain can move water without treating it or reducing the total harm.'),
'06-03':('Visual-quality assessment needs defined indicators and relevant perspectives rather than an unexplained personal judgement.','An unfamiliar building style is not automatically environmental damage.'),
'06-04':('Noise effects depend on sound level, timing, duration and affected users.','A short special-event observation does not establish normal or night-time conditions.'),
'06-05':('Urban sprawl is outward expansion of the built area and can include formal housing, shopping, industry or sports uses.','A footprint change does not establish an equal population or pollution percentage change.'),
'91':('Traffic counts need defined lines, categories, directions, durations and safe observation positions.','A short count projected to an hour is an estimate under an assumption rather than an observed hour.'),
'92':('Pedestrian counts record defined crossings rather than necessarily unique shoppers.','Comparisons with different observation durations require suitable rates or matched intervals.'),
'93':('Shopping questionnaires and land-use transects produce different evidence with defined eligible groups or routes.','Mixed-use classification, non-response and site/time coverage affect interpretation.')}
CARDS={
'001':('Name the rural pattern with dwellings grouped in a compact cluster.','Nucleated settlement.',['1 mark for the pattern name nucleated.']),
'002':('Describe the supplied equal-scale settlement panels, each with eight house symbols: A spread among plots, B along one east–west route and C grouped at a crossroads.','A is dispersed, B linear and C nucleated. Equal house counts have different arrangements. The panels establish form rather than household wealth or an exact historical cause.',['1 mark for the three-way arrangement pattern; 1 for the equal-count/spatial evidence; 1 for the bounded interpretation.']),
'003':('Describe panel A of the supplied settlement plan: eight dwelling symbols lie apart with agricultural plots between, and service data are absent.','The dwellings are dispersed across intervening land. The plot evidence supports the spacing description. It does not establish lack of services or the purpose of all farm output.',['1 mark for the dispersed pattern; 1 for spacing/plot evidence; 1 for the service/purpose limit.']),
'004':('Describe panel B: dwelling symbols extend along an east–west route rather than forming a compact cluster.','The settlement is linear along the route. Its elongated alignment is the distinguishing feature. Route access is a plausible influence, but the map alone does not prove its historical cause.',['1 mark for the linear pattern; 1 for alignment evidence; 1 for the bounded causal interpretation.']),
'005':('Describe panel C: dwelling symbols cluster around a crossroads, with no household income data supplied.','The arrangement is nucleated around the junction. The concentration differs from scattered or route-long spacing. The cluster alone does not establish income or total town size beyond the symbols.',['1 mark for the cluster pattern; 1 for crossroads evidence; 1 for the size/income limit.']),
'006':('Explain how a narrow usable valley strip can help produce linear settlement where it contains the practical access route.','Relief limits feasible building ground to an elongated strip. The route provides access along it, favouring dwellings aligned with the corridor. The pattern depends on the stated land/access conditions rather than a universal valley rule.',['1 mark for relief as a factor; 1 for the usable-strip link; 1 for route access; 1 for the conditional alignment effect.']),
'007':('Describe the rural comparison: A clusters near a shared water point and school; B has homes on separate farm plots with road links. Rainfall is stated equal.','A has shared-node concentration and B dispersed plot-related locations. The evidence supplies water/service and land-organisation differences despite equal rainfall. It does not establish different household wealth.',['1 mark for the paired pattern; 1 for the matched-rain/different-arrangement evidence; 1 for the bounded explanation.']),
'008':('Name the terrain factor represented by slope and elevation when assessing a settlement site.','Relief.',['1 mark for the factor name relief.']),
'009':('Name the locational quality describing practical ease of reaching services, work or markets.','Accessibility.',['1 mark for the concept name accessibility.']),
'010':('Name one farming arrangement that can influence dwelling spacing, without proving its income or purpose.','The distribution of holdings, fields or grazing/work areas.',['1 mark for a relevant land-arrangement point.']),
'011':('Name one political or historical influence on rural settlement sites.','Land allocation, planned settlement or relevant historical restrictions.',['1 mark for a relevant influence name.']),
'012':('Explain how a new usable employment function can support settlement growth where housing and access permit.','The function creates livelihood opportunities and demand for related services. People may move towards those opportunities, adding to local population and service needs. Actual growth also depends on other components and available capacity.',['1 mark for employment as a factor; 1 for the livelihood/service link; 1 for possible residential movement; 1 for the conditional growth effect.']),
'013':('Describe this country’s urban change: urban population rises from 400 of 1,000 to 600 of 1,200, using compatible definitions.','Urban numbers rise by 200 and the share rises from 40% to 50%. Both urban growth and urbanisation occur. The totals do not isolate migration from natural change or reclassification.',['1 mark for the number/share pattern; 1 for numerical evidence; 1 for the component-cause limit.']),
'014':('Name the urban zone with a concentration of commercial and business functions.','Central business district or CBD.',['1 mark for the zone name CBD.']),
'015':('Describe the supplied schematic urban plan: CBD at the central junction, housing west/south, industry beside an eastern freight corridor, shopping strip north and park south-east.','Functions occupy different connected locations rather than one identical zone. Industry relates spatially to freight access and the CBD to the junction, while housing, retail and open space have distinct positions. The schematic is not a measured map of Windhoek or proof of incomes.',['1 mark for the differentiated land-use pattern; 1 for correct paired spatial evidence; 1 for the model/real-city limitation.']),
'016':('Describe the CBD evidence on the supplied plan: offices, shops and services concentrate near the central route junction; height and income are unrecorded.','The commercial concentration and access node support CBD interpretation. The evidence concerns functions and location. It does not establish the tallest building or household wealth.',['1 mark for the functional-concentration pattern; 1 for junction/use evidence; 1 for the height/income limit.']),
'017':('Describe the residential evidence: housing zones occupy west/south positions, with buildings of varied form but no income or service records.','Housing use is mapped in the stated zones. Form can vary within residential land use. The plan does not establish household income, occupancy or reliable service access.',['1 mark for the residential-zone pattern; 1 for position/form evidence; 1 for the social/service limitation.']),
'018':('Describe the industrial zone beside the eastern freight corridor in the supplied plan; no emission or employment totals are given.','The land-use key identifies industry and its position relates to freight access. That is a locational relationship, not a measured transport-cost saving. The plan does not establish pollution or job totals.',['1 mark for the industry/access relationship; 1 for keyed position evidence; 1 for the outcome limitation.']),
'019':('Describe the shopping pattern: the plan has central retail plus a northern shopping strip beside an access route; customer origins are unrecorded.','Shopping is distributed across central and strip locations. The strip relates to the route rather than replacing every central shop. Its customer catchment cannot be established without appropriate evidence.',['1 mark for the multiple-node pattern; 1 for position/access evidence; 1 for the catchment limitation.']),
'020':('Describe the open-space evidence: a south-eastern area is keyed as a park, but maintenance and public-access records are absent.','The plan identifies a park/open-space location. It distinguishes that use from built zones. It does not establish actual maintained access or all ecological functions without further evidence.',['1 mark for the mapped-use pattern; 1 for key/position evidence; 1 for the delivery limitation.']),
'021':('Describe the transport evidence: routes meet at the CBD and a freight corridor reaches eastern industry, but frequencies and capacity are absent.','The plan shows connections serving different functions. Route convergence supports central access and the corridor links industry. It does not establish affordable transport, congestion levels or unlimited capacity.',['1 mark for the functional-network pattern; 1 for paired route evidence; 1 for the service/capacity limit.']),
'022':('Name one housing response that can improve existing areas rather than assume all residents must relocate.','Suitable informal-settlement upgrading or service improvement.',['1 mark for a relevant response name.']),
'023':('How far do you agree that the cheapest housing charge is the most affordable complete option? Monthly housing/transport/services costs are A N$900/600/300 and B N$1,000/200/200; other costs and quality are unspecified.','Disagree from those costs. A totals N$1,800 and B N$1,400, so A’s lower housing charge is outweighed by transport and service costs. B is lower for the stated bundle, but complete suitability and affordability require the remaining costs, income and conditions.',['Up to 4 C marks for judgement using the cost evidence, both totals and the bundle-versus-housing distinction.','1 C mark for a supported bounded affordability decision.']),
'024':('Name the CBD access problem indicated by queues or delays when movement exceeds usable space/capacity.','Congestion.',['1 mark for the problem name congestion.']),
'025':('Name the housing problem where available accommodation is unaffordable, unsuitable or inaccessible to people needing it.','Housing shortage or inadequate housing access.',['1 mark for a relevant housing-problem name.']),
'026':('Name the improvement approach providing suitable services or housing changes in an existing informal area.','Settlement upgrading.',['1 mark for the approach name upgrading.']),
'027':('Name one transport measure that can reduce a specific car-access pressure where it is reliable, affordable and useful for relevant journeys.','Suitable public transport or a relevant managed-demand/access measure.',['1 mark for a relevant measure name.']),
'028':('Explain how outward urban building can increase runoff where vegetation is replaced by hard surfaces and drainage capacity is unchanged.','Hard surfaces can reduce infiltration and route water rapidly. More quick runoff reaches drains/channels, potentially exceeding capacity. Local flood or pollution pressure can then rise under the relevant storm conditions.',['1 mark for hard-surface expansion as a factor; 1 for the infiltration/runoff link; 1 for drainage loading; 1 for the conditional environmental effect.']),
'029':('Describe the fixed-boundary land-cover account: built area grows from ten to fifteen square units; population and prior land-use types are not supplied.','The built footprint expands five units, a 50% increase. It establishes outward spatial growth under the classification. It does not establish equal population growth or that every converted unit was farmland.',['1 mark for the footprint-change pattern; 1 for numerical evidence; 1 for the population/land-type limitation.']),
'030':('Name one urban air-pollution source, distinct from a measured concentration.','Vehicle emissions, industrial emissions or relevant burning.',['1 mark for a relevant source name.']),
'031':('Name one pathway causing urban water pollution.','Unsuitable sewage discharge, industrial waste or contaminated runoff reaching water.',['1 mark for a relevant pathway name.']),
'032':('Name the environmental-quality category concerned with unwanted appearance effects from unmanaged litter or dereliction under stated criteria.','Visual pollution.',['1 mark for the category name visual pollution.']),
'033':('Name the pollution category involving unwanted sound and its effects on relevant users.','Noise pollution.',['1 mark for the category name noise pollution.']),
'034':('Name outward expansion of the urban built area, including possible formal housing, industry or shopping development.','Urban sprawl.',['1 mark for the process name urban sprawl.']),
'035':('Describe a safe traffic-count sequence for comparing two routes over matched periods.','Define safe observation points, counting lines and categories; tally vehicles consistently for equal stated intervals; record totals, directions and context before comparing.',['1 mark for the first definition/safety step; 1 for the matched counting sequence; 1 for the usable record/result.']),
'036':('Explain why a larger traffic count alone does not establish worse congestion.','Delay depends on usable capacity and timing as well as demand. A larger road can carry more traffic with less delay, so appropriate flow/capacity or journey-time evidence is needed.',['1 mark for the capacity/timing reason; 1 for explaining the required delay/access evidence.']),
'037':('Describe a pedestrian-count sequence distinguishing passages from unique people.','Define a crossing line and rule; tally each qualifying passage during the matched interval from a safe position; record duration, direction and repeated-passage limitations.',['1 mark for the first operational-definition step; 1 for the safe tally sequence; 1 for the duration-labelled record/result.']),
'038':('Explain why thirty crossings in ten minutes can represent a higher pedestrian rate than forty in twenty minutes.','The observation durations differ. Rates are three and two crossings per minute, so comparing raw totals alone reverses the rate judgement.',['1 mark for the unequal-duration reason; 1 for the correct matched-rate explanation.']),
'039':('Describe a sequence for a shopping-area land-use transect with mixed shops and flats.','Define the route, stations and classification including mixed use; record uses consistently along it with uncertainty noted; summarise the route pattern without treating it as the entire city.',['1 mark for the first route/key step; 1 for the consistent classification sequence; 1 for the recorded pattern/result and scale limit.']),
'040':('Explain why questionnaires taken only inside one shop may not represent all users of the wider centre.','The selection excludes people using other premises or not entering that shop. A broader suitable site/time selection is needed because the sample frame does not cover the target population.',['1 mark for the coverage-bias reason; 1 for explaining the suitable selection remedy.']),
'041':('Explain the error in defining urbanisation only as rural–urban movement. What measure discriminates it?','The confusion substitutes one possible cause for the population-share change. Urbanisation is a rising urban proportion; migration, natural change and classification can contribute. Compare compatible urban and total populations to test the share.',['1 mark for the cause/definition confusion; 1 for the correct distinction and urban-share test.']),
'042':('Explain the error in treating urban sprawl as only informal housing or migration. What evidence tests sprawl?','The confusion substitutes a housing category or movement for outward built-area expansion. Formal estates, shopping or industry can expand the footprint too. Compare compatible dated built-area maps to discriminate the spatial process.',['1 mark for the category/process error; 1 for the correct footprint distinction and dated-map test.']),
'043':('Explain the error in concluding that a tall residential building proves high income or quality of life. What evidence discriminates form from living conditions?','The confusion treats building height as household welfare. Occupancy, affordability, services and appropriate household evidence are needed; height alone describes form. Compare those conditions to test the social claim.',['1 mark for the form/welfare confusion; 1 for the correct distinction and relevant living-condition test.'])}
TASKS=[
{'objectives':['01','02','03'],'prompt':'(a) Name the rural pattern of a compact dwelling cluster. [1]\n(b) Describe three distinct influences on rural settlement sites or arrangement. [3]\n(c) Name the measure describing a rising proportion living in urban areas. [1]\n(d) Describe the urban change: 400 of 1,000 residents urban before; 600 of 1,200 after, with compatible definitions. [2]','answer':'(a) Nucleated. (b) Suitable relief/usable water can shape feasible sites; access connects homes to services/markets; agricultural holdings or policy can shape spacing. Credit three distinct supported factor descriptions. (c) Urbanisation. (d) Urban count rises 200 while its share rises from 40% to 50%; both urban growth and urbanisation occur.','guide':['(a) 1 A mark for nucleated.','(b) 3 A marks for three distinct settlement-factor point descriptions.','(c) 1 A mark for urbanisation.','(d) 2 B marks for the number and share interpretations.'],'split':{'A':5,'B':2},'parts':[('a','Name',1,'A'),('b','Describe',3,'A'),('c','Name',1,'A'),('d','Describe',2,'B')]},
{'objectives':['04','05','06'],'prompt':'Two hypothetical housing locations have monthly housing/transport/service costs: A N$900/600/300; B N$1,000/200/200. The household has N$1,500 for these specified costs. Other expenses and housing quality are not supplied.\n(a) Name the locational concept relating to practical journeys to jobs and services. [1]\n(b) Calculate B’s combined specified monthly cost. [2]\n(c) Describe three distinct supported cost/budget comparisons. [3]\n(d) What judgement is supported about the claim “B must be the better complete housing solution”? [1]','answer':'(a) Accessibility. (b) 1,000+200+200 = N$1,400 per month. (c) A has a lower housing charge but higher combined total, N$1,800 versus N$1,400; A exceeds the specified budget by N$300; B is N$100 below it. Credit distinct comparisons without repeated credit for equivalent expressions of one total difference. (d) B fits the stated cost bundle better, but complete suitability is not established without other expenses, quality and access evidence.','guide':['(a) 1 A mark for accessibility.','(b) 2 B marks for the sum method and correct total with currency/period.','(c) 3 B marks for distinct resource-based comparison patterns and budget evidence.','(d) 1 C mark for a supported bounded suitability judgement.'],'split':{'A':1,'B':5,'C':1},'parts':[('a','Name',1,'A'),('b','Calculate',2,'B'),('c','Describe',3,'B'),('d','What',1,'C')]},
{'objectives':['05','05-02','05-03'],'prompt':'How far do you agree that Windhoek’s Informal Settlement Upgrading Project title alone proves all housing needs are met? City information describes collaborative affordable-housing work on serviced land, and NHE recorded a 2020 phase launch at Havana Proper. This resource supplies no complete current need, affordability or household-outcome account. Judge the evidence. [5]','answer':'Disagree with the complete-success claim. The sources establish a project and approach, not a reconciled current housing outcome for every household. Suitable structures, usable services, affordability, location and continuing need require appropriate records. Upgrading can contribute while a wider gap remains. A historical launch or project name is not proof of completed citywide delivery.','guide':['Up to 4 C marks for judgement using the case evidence, launch/outcome distinction and missing affordability/service/need records.','1 C mark for a supported decision recognising potential contribution without claiming all needs met.'],'split':{'C':5},'parts':[('a','How far do you agree',5,'C')]}
]
SOURCES=[('CITY-WINDHOEK-UPGRADING','https://www.windhoekcc.org.na/the-informal-settlement-upgrading-project/'),('NHE-UPGRADING-2020','https://www.nhe.com.na/informal-settlement-upgrading-project/'),('UN-HABITAT-NAMIBIA-UPGRADING','https://unhabitat.org/node/160776'),('WJEC-LAND-USE-CONCEPTS','https://resource.download.wjec.co.uk/vtc/2023-24/mfw/mfw23-24_10-16/pdf/_en/1-4-2_urban-land-use-patterns.pdf')]
if __name__=='__main__':
 assemble('3.3',FACTS,CARDS,TASKS,SOURCES)
 td=W/'topics/3.3';wo=read(td/'work_order.json');p=td/wo['output_files']['learning_items'];d=read(p);reuses=[]
 for i in d['items']:
  num=i['item_id'].split('-')[-2]
  r='VIS-6137-3.3-01' if num in ['003','004','005'] else 'VIS-6137-3.3-02' if num in ['016','017','018','019','020','021'] else None
  if r:
   i['context']['situation']='VISUAL PENDING: reuse of '+r+' with the keyed panel/zone named in the prompt; Claude authoring and separate Codex review pending.';stamp(i,i['claim_ids']);reuses.append({'item_id':i['item_id'],'resource_id':r})
 dump(p,d);n=read(td/'authoring_notes.json');n['visual_reuses']=reuses;n['model_boundary']='Both urban comparison panels are explicitly schematic. Neither is a measured Windhoek map or a universal LEDC/MEDC income layout. All rural panels use eight dwellings so pattern is separated from count.';dump(td/'authoring_notes.json',n)
